INSERT INTO purpose VALUES('theory-cell-complexes-tools','adversarial::AlphabetLie','trait','Names the answers a `Lying` alphabet may give dishonestly, so an adversary overrides exactly the one it lies about.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cell-complexes-tools','adversarial::CollidingAddresses','struct','Holds the adversary that hashes every orientation tag to nothing, so two cells differing only in orientation collide.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cell-complexes-tools','adversarial::IncomparablePositions','struct','Holds the adversary that calls every position pair disjoint, so an application enclosing another is licensed to commute with it.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cell-complexes-tools','adversarial::Lying','struct','Holds the toy alphabet in every answer but the ones an `AlphabetLie` overrides, so a behaviour over `Lying<L>` is attributable to `L`''s one lie.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cell-complexes-tools','adversarial::LyingOrient','struct','Holds the orientation tag a `Lying` alphabet hashes, so every adversary but `CollidingAddresses` hashes a cell exactly as the toy cell.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cell-complexes-tools','adversarial::NonLocalSplice','struct','Holds the adversary that disturbs a sibling of the position it splices, so two applications at disjoint positions do not commute.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cell-complexes-tools','adversarial::WithheldConvexity','struct','Holds the adversary that withholds the convexity warrant, so a commutation check''s convexity conjunct refuses every pair.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cell-complexes-tools','adversarial::lying_cell','function','Builds a `Lying` cell, so the adversary''s lie is exercised over a cell.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cell-complexes-tools','adversarial::reoriented_lying_cell','function','Builds a `Lying` cell with a reoriented tag, so the adversary''s hash lie is exercised.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cell-complexes-tools','toy::Toy','struct','Holds a toy term, so the term''s nodes are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cell-complexes-tools','toy::ToyAlphabet','struct','Holds the toy alphabet marker, so the alphabet''s inhabitant laws are exercised.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cell-complexes-tools','toy::ToyMeta','struct','Holds a toy metavariable''s metadata, so the metavariable''s name is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cell-complexes-tools','toy::ToyOrient','enum','Names a toy cell''s orientation, so the orientation''s kind is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cell-complexes-tools','toy::ToyPos','struct','Names a toy term''s position, so the position''s path is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cell-complexes-tools','toy::ToyProv','enum','Names a toy cell''s provenance, so the provenance''s kind is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cell-complexes-tools','toy::ToyRef','struct','Holds a toy subterm borrowed from a term, so a match and a substitution read it in place.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cell-complexes-tools','toy::ToySubst','struct','Holds a toy substitution, so the substitution''s bindings are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cell-complexes-tools','toy::ToyVar','struct','Holds a toy metavariable name, so the name''s text is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cell-complexes-tools','toy::toy_cell','function','Builds a toy cell, so the cell''s fields are read.',NULL,'fits','sound',NULL);
